package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_37_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Create two arrays of different types
        Integer[] array1 = {1, 2, 3};
        String[] array2 = {"a", "b", "c"};

        try {
            // This should throw an IllegalArgumentException due to incompatible types
            ArrayUtils.addAll(array1, array2);
            fail("Expected IllegalArgumentException due to incompatible array types");
        } catch (IllegalArgumentException e) {
            // Expected exception
            assertEquals("Cannot store java.lang.String in an array of java.lang.Integer", e.getMessage());
        }
    }
}

